-- V96: Expand principles 02–04 only. Principle 01 and all coaching scripts remain untouched.
begin;
update public.leader_playbook set title = 'Tư Duy Tảng Băng Trôi (The Iceberg Model)', content = 'Biểu hiện bên ngoài chỉ là 10% bề nổi. 90% phần chìm là nỗi sợ, áp lực tài chính, khủng hoảng cá nhân. Hãy đào sâu qua các case sau:', mini_quiz = null, learning_carousel = '{"situations":[{"question":"🔥 Case 1: Một đại lý mới liên tục trễ deadline nộp báo cáo tuần. Phản xạ đầu tiên của bạn là gì?","options":["A. Nhắc nhở quy định phạt của văn phòng","B. Đặt câu hỏi: ''Dạo này em có đang vướng mắc gì không?''"],"correct_index":1,"correct_explanation":"Tuyệt vời! Bạn đang chạm vào 90% phần chìm. Có thể họ đang gặp khủng hoảng thời gian hoặc chưa hiểu cách làm báo cáo.","wrong_explanation":"Phạt ngay lập tức chỉ mới tác động vào 10% bề nổi. Góc nhìn này dễ làm TVV bất mãn. Hãy lùi lại tìm hiểu nguyên nhân gốc rễ."},{"question":"🔥 Case 2: TVV bỗng nhiên im lặng, không tương tác trong group Zalo team suốt 3 ngày. Bạn xử lý thế nào?","options":["A. Nhắn tin riêng hỏi thăm nhẹ nhàng xem bạn có ổn không","B. Nhắc nhở chung trên group yêu cầu mọi người tương tác đủ"],"correct_index":0,"correct_explanation":"Chính xác! Sự im lặng đột ngột là tín hiệu chìm của áp lực hoặc biến cố. Quan tâm 1-1 sẽ chạm đến trái tim họ.","wrong_explanation":"Nhắc nhở chung lúc này mang tính áp đặt và không giải quyết được vấn đề cá nhân của TVV đó."},{"question":"🔥 Case 3: Một TVV kỳ cựu đột nhiên đòi tăng tỷ lệ hỗ trợ (cắt máu) cho khách hàng, nếu không sẽ nghỉ. Phần chìm 90% có thể là gì?","options":["A. Họ đang tham lam và muốn vòi vĩnh thêm tiền","B. Họ đang chịu áp lực tài chính lớn hoặc cảm thấy không được Leader trân trọng"],"correct_index":1,"correct_explanation":"Đúng vậy! Đòi hỏi tiền bạc đôi khi chỉ là vỏ bọc (10%) cho việc họ cảm thấy những cống hiến của mình không được ghi nhận (90%).","wrong_explanation":"Dán nhãn ''Tham lam'' sẽ cắt đứt đường lùi của cả hai. Hãy tìm hiểu xem dạo này cuộc sống của họ có biến cố gì không."},{"question":"🔥 Case 4: TVV mới đi làm được 1 tháng đã nhắn tin: ''Chắc em không hợp với nghề này đâu chị ạ''. Thay vì động viên ''Cố lên'', bạn nên hỏi gì?","options":["A. ''Khách hàng vừa nói gì khiến em tổn thương đúng không?''","B. ''Thế giờ em định xin việc ở đâu?''"],"correct_index":0,"correct_explanation":"Rất tinh tế! Lời đòi nghỉ việc (10%) thường xuất phát từ một cú sốc cụ thể vấp phải lúc đi tư vấn (90%). Gọi đúng tên nỗi đau sẽ giúp họ mở lòng.","wrong_explanation":"Câu hỏi này mang tính buông xuôi. Hãy cố gắng cứu vãn bằng cách tìm hiểu cú sốc nào đã khiến họ nản chí."}],"summary":{"title":"🎯 TỔNG KẾT & NEO KIẾN THỨC","content":"Đừng bao giờ phản ứng vội vàng với hiện tượng bề nổi. Kỷ luật mà thiếu sự thấu cảm sẽ chỉ tạo ra khoảng cách.","homework":"📝 BÀI TẬP NHỎ: Hôm nay, hãy chọn 1 TVV đang có vẻ chìm lắng và nhắn tin hỏi thăm riêng một cách chân thành nhất."}}'::jsonb where type = 'principle' and prefix = '02';
update public.leader_playbook set title = 'Kỹ thuật Đào Sâu Gốc Rễ (5 Whys)', content = 'Đừng làm ''từ điển sống'' giải quyết hộ tuyến dưới. Hãy dùng chuỗi câu hỏi ''Tại sao'' để họ tự ngộ ra vấn đề.', mini_quiz = null, learning_carousel = '{"situations":[{"question":"🔥 Case 1: TVV than vãn: ''Em không tìm được khách hàng nào cả''. Đâu là câu hỏi khơi gợi?","options":["A. Sao em không thử gọi lại danh sách khách cũ?","B. Theo em, vì sao dạo này mình lại khó kết nối với khách vậy?"],"correct_index":1,"correct_explanation":"Đúng! Câu (B) buộc TVV phải tự phân tích xem khâu tiếp cận hay kịch bản của mình đang vướng ở đâu.","wrong_explanation":"Bạn lại mắc bệnh mớm sẵn giải pháp rồi. Hãy để họ tự suy nghĩ bằng câu hỏi mở."},{"question":"🔥 Case 2: TVV nói ''Khách chê bảo hiểm đắt quá''. Bạn dùng câu Why tiếp theo thế nào?","options":["A. ''Vậy em thử thiết kế gói thấp hơn xem''","B. ''Theo em, vì sao khách lại thấy số tiền đó là đắt so với giá trị nhận lại?''"],"correct_index":1,"correct_explanation":"Chính xác! Đào sâu vào nhận thức giúp TVV nhận ra họ chưa neo được ''giá trị sinh mạng'', khiến khách chỉ nhìn vào ''giá cả''.","wrong_explanation":"Hạ gói phí ngay là cách giải quyết ngọn. Hãy giúp TVV hiểu lý do vì sao họ chưa thuyết phục được khách về mặt giá trị."},{"question":"🔥 Case 3: TVV phản hồi: ''Vì em chưa biết cách kể chuyện thực tế cho khách nghe''. Tiếp tục đào sâu thế nào?","options":["A. ''Điều gì làm em e ngại khi chia sẻ những câu chuyện thực tế bồi thường?''","B. ''Thế chị gửi cho em mấy bài mẫu để học thuộc nhé''"],"correct_index":0,"correct_explanation":"Tuyệt vời! Bạn đang đi đến tầng sâu nhất: Sự tự ti hoặc thiếu chất liệu thực tế của TVV.","wrong_explanation":"Đưa bài mẫu là làm thay. Cần tìm hiểu xem họ sợ sai, sợ nói gở, hay thực sự không có câu chuyện nào để kể."},{"question":"🔥 Case 4: Áp dụng 5 Whys, điểm dừng cuối cùng của chuỗi câu hỏi là khi nào?","options":["A. Khi TVV tự nhận ra lỗi do chính bản thân họ và tự đề xuất hướng hành động","B. Khi bạn đã hỏi đủ 5 câu dù TVV không trả lời được"],"correct_index":0,"correct_explanation":"Đích đến hoàn hảo! 5 Whys chỉ là tên gọi, quan trọng là giúp TVV chuyển từ ''Đổ lỗi hoàn cảnh'' sang ''Chịu trách nhiệm cá nhân''.","wrong_explanation":"Không cần cứng nhắc phải đủ 5 câu. Chỉ cần TVV tự nhận ra vấn đề nội tại của mình là cuộc Khai vấn thành công."}],"summary":{"title":"🎯 TỔNG KẾT & NEO KIẾN THỨC","content":"Đưa ra câu trả lời chỉ giúp họ giải quyết 1 lần. Dạy họ cách đặt câu hỏi sẽ giúp họ tự giải quyết hàng ngàn lần.","homework":"📝 BÀI TẬP NHỎ: Trong cuộc họp 1-1 tới, tuyệt đối không đưa ra lời khuyên ngay. Hãy thử dùng ít nhất 3 câu hỏi ''Tại sao/Như thế nào''."}}'::jsonb where type = 'principle' and prefix = '03';
update public.leader_playbook set title = 'Khung Phản Hồi Đa Chiều (SBI Model)', content = 'Situation (Tình huống) - Behavior (Hành vi khách quan) - Impact (Tác động). Góp ý vào hành vi, tuyệt đối không dán nhãn con người.', mini_quiz = null, learning_carousel = '{"situations":[{"question":"🔥 Case 1: Một Top Sale có thái độ trịch thượng trong cuộc họp. Đâu là cách nói chuẩn chữ B (Behavior)?","options":["A. Dạo này em làm việc rất kiêu ngạo","B. Sáng nay lúc họp, em ngắt lời bạn A hai lần"],"correct_index":1,"correct_explanation":"Quá chuẩn! Bạn nêu rõ sự kiện và hành vi đếm được, không hề tấn công cá nhân.","wrong_explanation":"''Kiêu ngạo'' là nhãn dán chủ quan, sẽ khiến Top Sale lập tức xù lông phòng thủ."},{"question":"🔥 Case 2: Sau khi nêu Behavior, đến phần Impact (Tác động), bạn nên nói gì?","options":["A. Làm vậy là vi phạm văn hóa công ty đấy nhé!","B. Việc đó làm các bạn mới cảm thấy e ngại, không dám phát biểu thêm"],"correct_index":1,"correct_explanation":"Chính xác! Chỉ ra tác động thực tế đến cảm xúc của người khác giúp nhân sự tự nhìn nhận lại hậu quả.","wrong_explanation":"Dùng nội quy để ép buộc sẽ làm lu mờ đi ý nghĩa giáo dục của phản hồi mang tính xây dựng."},{"question":"🔥 Case 3: Một TVV thường xuyên ăn mặc xuề xòa đi gặp khách. Bạn dùng chữ S (Tình huống) như thế nào để bắt đầu?","options":["A. ''Chị thấy dạo này em ăn mặc lôi thôi quá''","B. ''Hôm thứ Ba, lúc chị em mình đi gặp anh khách hàng VIP ở quán cafe...''"],"correct_index":1,"correct_explanation":"Đúng! Neo vào một thời gian, địa điểm cụ thể (Thứ Ba, quán cafe) giúp cuộc trò chuyện khách quan và không mang tính vơ đũa cả nắm.","wrong_explanation":"Bắt đầu bằng từ ''Dạo này'' rất chung chung và giống một lời chỉ trích, khiến người nghe khó chịu ngay từ giây đầu tiên."},{"question":"🔥 Case 4: Sau khi nói xong S-B-I, bước cuối cùng để chốt lại cuộc góp ý là gì?","options":["A. Yêu cầu họ cam kết không tái phạm","B. Đặt câu hỏi: ''Góc nhìn của em về việc này như thế nào?''"],"correct_index":1,"correct_explanation":"Tuyệt vời! Luôn kết thúc bằng một câu hỏi mở để họ có quyền phản biện hoặc tự nguyện thay đổi.","wrong_explanation":"Ép cam kết sẽ biến cuộc góp ý thành một buổi cảnh cáo. Hãy cho họ không gian an toàn để tự lên tiếng."}],"summary":{"title":"🎯 TỔNG KẾT & NEO KIẾN THỨC","content":"Con người dễ dàng chấp nhận sửa đổi khi họ biết hành vi cụ thể nào đang ảnh hưởng xấu đến người khác, thay vì bị phán xét chung chung.","homework":"📝 BÀI TẬP NHỎ: Chuẩn bị một thông điệp góp ý theo đúng khung S-B-I cho một vấn đề tồn đọng trong tuần này."}}'::jsonb where type = 'principle' and prefix = '04';
commit;
